import React, { useEffect, useMemo, useRef, useState } from 'react'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { AlertCircle, FileText, Loader2 } from 'lucide-react'
import { Worker, Viewer } from '@react-pdf-viewer/core'
import { defaultLayoutPlugin } from '@react-pdf-viewer/default-layout'
import '@react-pdf-viewer/core/lib/styles/index.css'
import '@react-pdf-viewer/default-layout/lib/styles/index.css'

const PDF_WORKER_URL = 'https://unpkg.com/pdfjs-dist@3.11.174/build/pdf.worker.min.js'

const resolveIsPdf = (doc) => {
  const mime = String(doc?.mimeType || '').toLowerCase()
  const fileType = String(doc?.fileType || '').toLowerCase()
  const name = String(doc?.name || '').toLowerCase()
  const sourceUrl = String(doc?.sourceUrl || '').toLowerCase()
  return (
    mime === 'application/pdf' ||
    mime.includes('/pdf') ||
    fileType === 'pdf' ||
    name.endsWith('.pdf') ||
    /\.pdf($|\?)/i.test(sourceUrl)
  )
}

const resolveIsDocx = (doc) => {
  const mime = String(doc?.mimeType || '').toLowerCase()
  const fileType = String(doc?.fileType || '').toLowerCase()
  const name = String(doc?.name || '').toLowerCase()
  const sourceUrl = String(doc?.sourceUrl || doc?.url || '').toLowerCase()
  return (
    mime.includes('wordprocessingml.document') ||
    mime.includes('msword') ||
    fileType === 'docx' ||
    fileType === 'doc' ||
    name.endsWith('.docx') ||
    name.endsWith('.doc') ||
    /\.docx?($|\?)/i.test(sourceUrl)
  )
}

const isDocxArchive = async (blob) => {
  if (!blob) return false
  const header = new Uint8Array(await blob.slice(0, 4).arrayBuffer())
  return header[0] === 0x50 && header[1] === 0x4b
}

const extractDocxPlainText = async (blob) => {
  const { default: JSZip } = await import('jszip')
  const zip = await JSZip.loadAsync(blob)
  const documentXml = zip.file('word/document.xml')
  if (!documentXml) return ''

  const xmlText = await documentXml.async('string')
  const decodeEntities = (value) =>
    String(value || '')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")

  const withParagraphBreaks = String(xmlText)
    .replace(/<w:br\s*\/?>/g, '\n')
    .replace(/<w:tab\s*\/?>/g, '\t')
    .replace(/<\/w:p>/g, '\n\n')

  const matches = Array.from(withParagraphBreaks.matchAll(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g))
  const extracted = matches
    .map((match) => decodeEntities(match[1]).trim())
    .filter(Boolean)
    .join(' ')

  return extracted.replace(/\n{3,}/g, '\n\n').trim()
}

const SitePackageDocumentViewerModal = ({
  open,
  onOpenChange,
  selectedDocument,
  isLoading = false,
  errorMessage = '',
}) => {
  const defaultLayoutPluginInstance = defaultLayoutPlugin()
  const docxContainerRef = useRef(null)
  const [docxLoading, setDocxLoading] = useState(false)
  const [docxError, setDocxError] = useState('')
  const [docxHasContent, setDocxHasContent] = useState(false)
  const isPdf = resolveIsPdf(selectedDocument)
  const isDocx = resolveIsDocx(selectedDocument)
  const canRenderPdf = Boolean(selectedDocument?.url && isPdf && !isLoading && !errorMessage)
  const canRenderDocx = Boolean(selectedDocument?.url && isDocx && !isLoading && !errorMessage)

  const effectiveError = useMemo(() => errorMessage || docxError, [errorMessage, docxError])

  useEffect(() => {
    let cancelled = false

    const renderDocx = async () => {
      if (!open || !canRenderDocx || !docxContainerRef.current) return

      try {
        setDocxLoading(true)
        setDocxError('')
        setDocxHasContent(false)
        const { renderAsync } = await import('docx-preview')
        let blob = null
        if (selectedDocument?.file instanceof Blob) {
          blob = selectedDocument.file
        } else {
          const resp = await fetch(selectedDocument.url)
          if (!resp.ok) {
            throw new Error(`Failed to fetch DOCX (${resp.status})`)
          }
          blob = await resp.blob()
        }
        if (!(await isDocxArchive(blob))) {
          throw new Error('The selected file is not a valid DOCX archive. Please re-upload or download the file to inspect it.')
        }
        if (cancelled || !docxContainerRef.current) return
        docxContainerRef.current.innerHTML = ''
        await renderAsync(blob, docxContainerRef.current, null, {
          className: 'docx-preview-wrapper',
          inWrapper: true,
          ignoreWidth: false,
          ignoreHeight: false,
          ignoreFonts: false,
          breakPages: true,
          ignoreLastRenderedPageBreak: true,
          experimental: false,
          trimXmlDeclaration: true,
          useBase64URL: true,
          renderHeaders: true,
          renderFooters: true,
          renderFootnotes: true,
          renderEndnotes: true,
        })
        const html = docxContainerRef.current?.innerHTML?.trim() || ''
        if (!html && !docxContainerRef.current?.children?.length) {
          throw new Error('DOCX preview did not produce any visible content')
        }
        setDocxHasContent(true)
      } catch (e) {
        if (!cancelled) {
          try {
            if (docxContainerRef.current) {
              const plainText = await extractDocxPlainText(blob)
              if (plainText) {
                docxContainerRef.current.innerHTML = `<div class="docx-plain-text"><pre>${plainText
                  .replace(/&/g, '&amp;')
                  .replace(/</g, '&lt;')
                  .replace(/>/g, '&gt;')}</pre></div>`
                setDocxHasContent(true)
                setDocxError('')
                return
              }
            }
          } catch (fallbackErr) {
            console.warn('DOCX fallback rendering failed:', fallbackErr)
          }
          setDocxError(e?.message || 'Unable to preview DOCX document inline.')
        }
      } finally {
        if (!cancelled) setDocxLoading(false)
      }
    }

    renderDocx()
    return () => {
      cancelled = true
    }
  }, [open, canRenderDocx, selectedDocument?.url, selectedDocument?.file])

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[95vw] w-[min(1100px,94vw)] h-[94vh] flex flex-col p-0 overflow-hidden bg-white dark:bg-slate-900 border-none shadow-[0_20px_50px_-12px_rgba(0,0,0,0.3)] rounded-2xl">
        <DialogHeader className="px-6 py-3 bg-white dark:bg-slate-950 border-b border-slate-100 dark:border-slate-800 shrink-0 flex-row items-center justify-between space-y-0">
          <div className="flex flex-col min-w-0 pr-8">
            <DialogTitle className="text-base font-bold text-slate-900 dark:text-slate-50 tracking-tight">
              View document
            </DialogTitle>
            <DialogDescription className="text-[10px] font-medium text-slate-400 truncate">
              {selectedDocument?.name || 'Loading...'}
            </DialogDescription>
          </div>
        </DialogHeader>

        <div className="flex-1 overflow-hidden relative bg-slate-50 dark:bg-slate-950 p-1 sm:p-2">
          <div className="w-full h-full rounded-lg overflow-hidden border border-slate-200 dark:border-slate-800 bg-white shadow-inner">
            {canRenderPdf ? (
              <Worker workerUrl={PDF_WORKER_URL}>
                <div style={{ height: '100%', width: '100%' }}>
                  <Viewer fileUrl={selectedDocument.url} plugins={[defaultLayoutPluginInstance]} />
                </div>
              </Worker>
            ) : canRenderDocx ? (
              <div className="h-full w-full overflow-auto bg-white p-4">
                {docxLoading ? (
                  <div className="flex flex-col items-center justify-center h-full gap-4 text-slate-400">
                    <Loader2 className="w-10 h-10 animate-spin text-blue-500" />
                    <p className="text-sm font-medium">Preparing DOCX preview...</p>
                  </div>
                ) : docxError ? (
                  <div className="flex flex-col items-center justify-center h-full gap-4 px-6 text-center">
                    <AlertCircle className="w-10 h-10 text-amber-500" />
                    <p className="text-sm font-medium text-slate-700 dark:text-slate-200">
                      {docxError}
                    </p>
                    {selectedDocument?.url ? (
                      <Button asChild variant="outline" size="sm">
                        <a href={selectedDocument.url} download={selectedDocument?.name || 'document'}>
                          <FileText className="w-4 h-4 mr-2" />
                          Download file
                        </a>
                      </Button>
                    ) : null}
                  </div>
                ) : null}
                {!docxLoading && !docxError && !docxHasContent ? (
                  <div className="flex flex-col items-center justify-center h-full gap-4 px-6 text-center">
                    <AlertCircle className="w-10 h-10 text-amber-500" />
                    <p className="text-sm font-medium text-slate-700 dark:text-slate-200">
                      Unable to render DOCX preview.
                    </p>
                  </div>
                ) : null}
                <div ref={docxContainerRef} className="w-full" />
                <style>{`
                  .docx-preview-wrapper { padding: 20px; background: white; }
                  .docx-preview-wrapper .docx-wrapper { background: white; padding: 20px; margin: 0 auto; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
                  .docx-preview-wrapper .docx-wrapper > section.docx { margin-bottom: 20px; box-shadow: 0 1px 4px rgba(0,0,0,0.1); }
                  .docx-plain-text { padding: 24px; color: #0f172a; }
                  .docx-plain-text pre { margin: 0; white-space: pre-wrap; word-break: break-word; font-family: inherit; font-size: 14px; line-height: 1.6; }
                `}</style>
              </div>
            ) : isLoading ? (
              <div className="flex flex-col items-center justify-center h-full gap-4 text-slate-400">
                <Loader2 className="w-10 h-10 animate-spin text-blue-500" />
                <p className="text-sm font-medium">Preparing document preview...</p>
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center h-full gap-4 px-6 text-center">
                <AlertCircle className="w-10 h-10 text-amber-500" />
                <p className="text-sm font-medium text-slate-700 dark:text-slate-200">
                  {effectiveError || 'Unable to preview document. Please download to view.'}
                </p>
                {!effectiveError && !isPdf && !isDocx ? (
                  <p className="text-xs text-slate-500">This file type is not supported for inline preview.</p>
                ) : null}
                {selectedDocument?.url ? (
                  <Button asChild variant="outline" size="sm">
                    <a href={selectedDocument.url} download={selectedDocument?.name || 'document'}>
                      <FileText className="w-4 h-4 mr-2" />
                      Download file
                    </a>
                  </Button>
                ) : null}
              </div>
            )}
          </div>
        </div>

        <div className="px-6 py-2 bg-slate-50 dark:bg-slate-900/50 border-t border-slate-100 dark:border-slate-800 flex justify-end shrink-0">
          <Button variant="secondary" size="sm" onClick={() => onOpenChange(false)} className="px-4 h-8 text-xs font-semibold hover:bg-slate-200 dark:hover:bg-slate-800 transition-colors">
            Close Viewer
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

export default SitePackageDocumentViewerModal
